function materialInfo(id){const m=state.materials.find(m=>m.id===id);if(!m)return;let countries=[];try{countries=JSON.parse(m.production_countries||'[]');}catch{}const risk=countries.map(code=>code+': '+(state.countryRisk.find(r=>r.country_code===code)?.risk_level||'NOT REVIEWED')).join('; ');drawer('<h2>Material Information · '+esc(m.material)+'</h2><p>Production country risk: '+esc(risk||'Production origin not provided')+'</p>'+ (roles('ADMIN','MARKETING','EUDR_REVIEWER')?'<form id="materialInfoForm">'+['commodity','common_species','scientific_name','hs_cn_code','quantity','quantity_uom','production_range'].map(k=>field(k,k.replace(/_/g,' '),'text',m[k]||'')).join('')+field('countries','Production countries (ISO codes, comma separated)','text',countries.join(','))+select('scope_status','Human scope assessment',['NOT_PROVIDED','REVIEW_REQUIRED','IN_SCOPE','OUT_OF_SCOPE'],m.scope_status||'NOT_PROVIDED')+field('scope_rule_version','Checked Annex I version','text',m.scope_rule_version||'')+select('metadata_source_document_id','Source for metadata',state.docs.filter(d=>d.case_id===m.case_id).map(d=>[d.id,d.name]),m.metadata_source_document_id||'')+field('metadata_reference','Source page and fields','text',m.metadata_reference||'',true)+field('legality','Legality evidence IDs (comma separated)','text',JSON.parse(m.legality_evidence_ids||'[]').join(','))+field('deforestation','Deforestation evidence IDs (comma separated)','text',JSON.parse(m.deforestation_evidence_ids||'[]').join(','))+'<button>Save source-backed information</button></form>':'<p>'+esc(m.scientific_name||'NOT PROVIDED')+'</p>'));if($('materialInfoForm'))$('materialInfoForm').onsubmit=e=>{e.preventDefault();const input=Object.fromEntries(new FormData(e.target)),list=s=>s.split(',').map(s=>s.trim()).filter(Boolean);input.production_countries=list(input.countries);input.legality_evidence_ids=list(input.legality);input.deforestation_evidence_ids=list(input.deforestation);delete input.countries;delete input.legality;delete input.deforestation;act('updateMaterialInfo',id,input);};}
