function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const action=b.dataset.action,id=b.dataset.id;try{
 if(action==='open')go('Workspace',id);else if(action==='newOrder')newOrder();else if(action==='openTasks')go('My Tasks');else if(action==='openOrders')go('Orders');else if(action==='document')await documentView(id);else if(action==='download')await download(id);else if(action==='upload')upload(id);else if(action==='assign')assignDialog(id);else if(action==='materials')materialsDialog(id);else if(action==='materialPrompt')await showPrompt(id,'MATERIAL_EXTRACTION');else if(action==='chain')chainDialog(id);else if(action==='geo')geoDialog(id);else if(action==='submit')await act('submitDocument',id);else if(action==='syncCalendar'){const r=await act('syncCalendar');if(r?.some(x=>x.status==='CALENDAR_ACCESS_REQUIRED'))$('msg').textContent='Calendar access required; tasks remain saved.';}
 else if(action.startsWith('prompt:'))await showPrompt(state.docs.find(d=>d.id===id).case_id,action.slice(7),id);else if(action.startsWith('processed:'))upload(id,action.slice(10));
 else if(action==='verifyProcessed'){const note=$('verificationNote').value.trim();if(!note)throw Error('Record verification checks in the review note first');await act('verifyProcessed',id,{verified:true,notes:note});}
 else if(action==='reviewGeo'){drawer('<h2>GEO review</h2><form id="geoReviewForm">'+select('status','Decision',['VERIFIED','REJECTED','MORE_INFO_REQUIRED'])+'<label>Review notes<textarea name="notes" required rows="4"></textarea></label><p>Verification does not certify deforestation-free status or legal compliance.</p><button>Record review</button></form>');$('geoReviewForm').onsubmit=e=>{e.preventDefault();act('reviewGeo',id,Object.fromEntries(new FormData(e.target)));};}
 else if(action==='closeOrder'){drawer('<h2>Close internal evidence workflow</h2><p>This records workflow closure. It does not certify EUDR compliance or submit a declaration.</p><form id="closeOrderForm"><label>Human review notes<textarea name="comment" required rows="4"></textarea></label><button>Confirm Internal Closure</button></form>');$('closeOrderForm').onsubmit=e=>{e.preventDefault();act('completeCase',id,{confirmed:true,comment:new FormData(e.target).get('comment')});};}else if(action==='materialInfo')materialInfo(id);else if(action==='certificate')certificateForm(id);else if(action==='readNotification')await act('markNotification',id);else if(action==='provision')await provisionUser(id);else if(action==='userForm')userForm(id);else if(action==='supplierForm')supplierForm(id);
 }catch(e){$('msg').textContent=errorLabel(e);}});}
load();
